function familyFrom(text){const t=String(text||'').toLowerCase().replaceAll('ё','е').replace(/№/g,' номер ');const words={одна:1,один:1,первый:1,первая:1,первую:1,первого:1,первой:1,раз:1,два:2,две:2,второй:2,вторая:2,вторую:2,второго:2,три:3,третий:3,третья:3,третью:3,третьего:3,третьей:3,четыре:4,четвертый:4,четвертая:4,четвертой:4,пять:5,пятый:5,пятая:5,пятой:5,шесть:6,шестой:6,шестая:6,семь:7,седьмой:7,седьмая:7,восемь:8,восьмой:8,восьмая:8,девять:9,девятый:9,девятая:9,девятой:9,десять:10,десятый:10,десятая:10,десятой:10};const unit='(?:семь[яюие]|пчелосемь[яюие]|ул(?:ей|ья|ье|ью)|ящик|семейк[ауи]|отвод(?:ок|ка|ку|ке|ком)|нуклеус(?:а|е|ом)?)',num='(\\d+|одна|один|перв(?:ый|ая|ую|ого|ой)?|раз|два|две|втор(?:ой|ая|ую|ого)?|три|трет(?:ий|ья|ью|ьего|ьей)|четыре|четверт(?:ый|ая|ую)|пять|пят(?:ый|ая)|шесть|шест(?:ой|ая)|семь|седьм(?:ой|ая)|восемь|восьм(?:ой|ая)|девять|девят(?:ый|ая)|десять|десят(?:ый|ая))',between='(?:\\s+[а-я-]+){0,3}?';for(const p of[new RegExp(`${unit}${between}\\s*(?:номер\\s*)?${num}`,'i'),new RegExp(`${num}${between}\\s*${unit}`,'i')]){const m=p.exec(t);if(m)return Number(m[1])||words[m[1]]||null}return null}
