function renderEntities(notes){
  const root=$('entities');if(activeType==='notes'||activeType==='treatment'){renderSimpleEntries(notes,root);return}const groups=entityGroups(notes,activeType);$('entity-count').textContent=countLabel(groups.filter(g=>g.family!==null).length,activeType);
  const filtered=groups.map(g=>({...g,tasks:taskRows(notes,g.type,g.family),latest:g.notes[0]})).filter(g=>{const open=g.tasks.filter(t=>!t.closed).length;return activeFilter==='all'||(activeFilter==='open'?open>0:open===0)});
  if(!filtered.length){root.innerHTML=`<div class="empty-state">${groups.length?'В этой категории ничего не найдено.':'Записей пока нет.'}</div>`;return}
  root.innerHTML=filtered.map(g=>{const open=g.tasks.filter(t=>!t.closed),latest=g.latest,facts=[['Матка',lastValue(g,'queen_year')],['Корм',lastValue(g,'feed')],['Сила семьи',lastValue(g,'strength')],['Количество рамок',lastValue(g,'frame_count')]].filter(([,v])=>v).map(([k,v])=>`${k}: ${v}`),summary=removeEntityPrefix(facts.join(' · ')||latest?.transcript||'Нет расшифровки',g.type,g.family);const title=g.family?`${g.type==='family'?'Семья':'Отводок'} №${g.family}`:`${g.type==='family'?'Семья':'Отводок'} · номер не указан`;return`<article class="entity-card" data-entity="${escapeHtml(g.key)}"><button class="entity-head" type="button" aria-expanded="false"><span class="entity-main"><span class="entity-title-line"><span class="entity-title">${title}</span>${open.length?`<span class="task-badge">${open.length} задач</span>`:''}</span><span class="entity-summary">${escapeHtml(summary)}</span>${open.length?`<span class="task-count">${open.length} невыполненных задач</span>`:''}</span><span class="expand-mark" aria-hidden="true">⌄</span></button><div class="entity-details">${facts.length?`<div class="facts">${facts.map(v=>`<span class="fact">${escapeHtml(removeEntityPrefix(v,g.type,g.family))}</span>`).join('')}</div>`:''}${open.length?`<h3 class="subheading">Что необходимо сделать</h3><div class="task-list">${open.map(t=>`<label class="task-row"><input type="checkbox" data-task="${escapeHtml(t.id)}"><span>${escapeHtml(t.text)}</span></label>`).join('')}</div>`:''}<h3 class="subheading">История</h3><div class="history-list">${g.notes.map(n=>`<div class="history-item"><span class="history-date">${fmtDateTime(n.createdAt)}</span>${escapeHtml(n.transcript||'Аудиозапись ждёт расшифровки')}<span class="history-tools"><button class="history-edit" type="button" data-edit-history="${escapeHtml(n.id)}" aria-label="Изменить запись">✎</button>${n.audio?`<button class="history-audio" data-play="${escapeHtml(n.id)}">▶ Аудиозапись</button>`:''}</span></div>`).join('')}</div></div></article>`}).join('');
  root.querySelectorAll('.entity-head').forEach(button=>wireEntityHead(button,button.closest('.entity-card').dataset.entity));
  root.querySelectorAll('[data-task]').forEach(input=>input.onchange=()=>{const closed=closedTasks();input.checked?closed.add(input.dataset.task):closed.delete(input.dataset.task);writeLocal(CLOSED_KEY,[...closed]);allNotes().then(renderEntities)});
  root.querySelectorAll('[data-play]').forEach(button=>button.onclick=()=>playAudio(button.dataset.play));
  root.querySelectorAll('[data-edit-history]').forEach(button=>button.onclick=()=>openHistoryEdit(button.dataset.editHistory));
}
function renderSimpleEntries(notes,root){const rows=notes.filter(n=>sectionOf(n)===activeType&&n.status!=='review').sort((a,b)=>a.createdAt-b.createdAt);$('entity-count').textContent=`${rows.length} ${activeType==='notes'?'записей':'обработок'}`;document.querySelector('.task-filters').hidden=true;if(!rows.length){root.innerHTML='<div class="empty-state">Записей пока нет.</div>';return}const numbers=new Map(rows.map((note,index)=>[note.id,index+1]));root.innerHTML=[...rows].reverse().map(note=>`<article class="simple-entry"><details><summary><span>${activeType==='notes'?'Заметка':'Обработка'} №${numbers.get(note.id)}</span><time>${fmtDateTime(note.createdAt)}</time></summary><div class="simple-entry-text">${escapeHtml(note.transcript||'Ожидает расшифровки')}</div><div class="history-tools"><button class="history-edit" type="button" data-edit-history="${escapeHtml(note.id)}" aria-label="Изменить запись">✎</button>${note.audio?`<button class="history-audio" data-play="${escapeHtml(note.id)}">▶ Аудиозапись</button>`:''}</div></details></article>`).join('');root.querySelectorAll('[data-play]').forEach(button=>button.onclick=()=>playAudio(button.dataset.play));root.querySelectorAll('[data-edit-history]').forEach(button=>button.onclick=()=>openHistoryEdit(button.dataset.editHistory))}
async function playAudio(id){const n=(await allNotes()).find(x=>x.id===id);if(n?.audio){const audio=new Audio(URL.createObjectURL(n.audio));audio.play()}}
function getMime(){return['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(x=>MediaRecorder.isTypeSupported(x))||''}
function elapsed(ms){const s=Math.floor(ms/1000);return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function openInput(kind){reviewNoteId=null;inputKind=kind;$('input-title').textContent=kind==='question'?(activeType==='notes'?'Спросить заметки':activeType==='treatment'?'Спросить лечение':'Вопрос по журналу'):(activeType==='notes'?'Новая заметка':activeType==='treatment'?'Новая запись о лечении':'Запись в журнал');$('input-methods').hidden=false;$('input-editor').hidden=true;$('input-result').hidden=true;$('input-text').value='';$('input-text').readOnly=false;$('input-status').textContent='Проверьте текст перед отправкой';$('record-status').hidden=true;$('input-back').textContent='Назад';$('input-back').hidden=false;$('input-send').hidden=false;$('input-send').textContent='Отправить';$('input-dialog').showModal()}
function showNoteReview(note){reviewNoteId=note.id;inputKind='note';$('input-title').textContent='Проверьте расшифровку';$('input-methods').hidden=true;$('input-result').hidden=true;$('input-editor').hidden=false;$('input-text').readOnly=false;$('input-text').value=note.transcript||'';$('input-status').textContent='Исправьте текст, затем отправьте в журнал';$('input-send').hidden=false;$('input-send').textContent='Отправить';$('input-back').hidden=false;$('input-back').textContent='Закрыть';$('input-dialog').showModal()}
function editMode(){ $('input-methods').hidden=true;$('input-editor').hidden=false;$('input-result').hidden=true;$('input-text').value='';$('input-text').readOnly=false;$('input-text').focus() }
function startInputTimer(){startedAt.input=Date.now();$('input-timer').textContent='00:00';timers.input=setInterval(()=>$('input-timer').textContent=elapsed(Date.now()-startedAt.input),250)}
function stopInputTimer(){clearInterval(timers.input);$('record-status').hidden=true;$('input-text').readOnly=false;$('input-status').textContent='Проверьте и исправьте распознанный текст перед отправкой'}
async function startAudioCapture(){if(inputKind==='question'&&!navigator.onLine){toast('Для голосового вопроса нужно подключение к интернету.');return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Запись недоступна. Выберите «Текстом» и используйте микрофон клавиатуры.');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),mime=getMime(),recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined),chunks=[];recorders[inputKind]=recorder;activeStreams[inputKind]=stream;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};editMode();$('input-text').readOnly=true;$('input-text').blur();$('record-status').hidden=false;$('input-back').hidden=true;$('input-send').disabled=false;$('input-send').textContent='Завершить запись';$('input-status').textContent='Говорите. Нажмите «Завершить запись», когда закончите.';startInputTimer();recorder.onstop=async()=>{clearInterval(timers.input);stream.getTracks().forEach(t=>t.stop());recorders[inputKind]=null;activeStreams[inputKind]=null;$('record-status').hidden=true;const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});if(inputKind==='note'&&!navigator.onLine){const note={id:crypto.randomUUID(),createdAt:Date.now(),audio:blob,transcript:'',family:null,entityType:'family',section:activeType,analysis:null,status:'pending'};await saveNote(note);$('input-dialog').close();toast('Аудиозапись сохранена. Расшифруем при подключении к интернету.');await refresh();return}try{$('input-status').textContent='Распознаю речь…';$('input-text').value=normalizeTranscript(await transcribe(blob));$('input-text').readOnly=false;$('input-status').textContent='Проверьте и исправьте текст перед отправкой'}catch(e){$('input-text').readOnly=false;$('input-status').textContent=e.message}finally{$('input-send').disabled=false;$('input-send').textContent='Отправить';$('input-back').hidden=false}};recorder.start()}catch{$('record-status').hidden=true;$('input-send').disabled=false;$('input-send').textContent='Отправить';$('input-back').hidden=false;$('input-status').textContent='Не удалось открыть микрофон. Разрешите доступ в браузере.';toast('Не удалось открыть микрофон.')}}
async function chooseVoice(){await startAudioCapture()}
async function submitInput(){const text=normalizeTranscript($('input-text').value.trim());if(!text){toast('Сначала введите или распознайте текст.');return}$('input-send').disabled=true;try{if(inputKind==='note'){let note;const requestedSection=reviewNoteId?(await allNotes()).find(n=>n.id===reviewNoteId)?.section||activeType:activeType,targetSection=sectionForText(text,requestedSection);if(reviewNoteId){note=(await allNotes()).find(n=>n.id===reviewNoteId);if(!note)return;note.transcript=text;note.section=targetSection;note.family=targetSection==='family'||targetSection==='nucleus'?familyFrom(text):null;note.entityType=targetSection==='nucleus'?'nucleus':targetSection==='family'?entityType(text):'family';note.analysis=null;note.status='pending'}else note={id:crypto.randomUUID(),createdAt:Date.now(),audio:null,transcript:text,family:targetSection==='family'||targetSection==='nucleus'?familyFrom(text):null,entityType:targetSection==='nucleus'?'nucleus':targetSection==='family'?entityType(text):'family',section:targetSection,analysis:null,status:'pending'};await saveNote(note);reviewNoteId=null;appendChat({role:'user',content:text,noteId:note.id});$('input-dialog').close();toast(targetSection==='notes'?'Заметка сохранена.':targetSection==='treatment'?'Обработка сохранена.':'Запись сохранена.');await setActiveType(targetSection==='nucleus'?'nucleus':targetSection==='family'?'family':targetSection);if(navigator.onLine){await processNote(note.id);processQueue()}}else{appendChat({role:'user',content:text});$('input-status').textContent='Ищу в журнале…';$('input-send').hidden=true;$('input-back').hidden=true;const answer=await askJournal(text);$('input-result').hidden=false;$('input-result').textContent=answer;$('input-editor').hidden=true;$('input-back').hidden=false;$('input-back').textContent='Новый запрос';if('speechSynthesis'in window){const speakButton=document.createElement('button');speakButton.type='button';speakButton.className='speak-answer';speakButton.textContent='▶ Прослушать ответ';speakButton.onclick=()=>speak(answer);$('input-result').append(speakButton)}appendChat({role:'assistant',content:answer})}}catch(e){toast(e.message)}finally{$('input-send').disabled=false}}
async function processNote(id){const note=(await allNotes()).find(n=>n.id===id);if(!note||note.status!=='pending'||!navigator.onLine)return false;status('Обрабатываем запись');try{if(!note.transcript){note.originalTranscript=await transcribe(note.audio);note.transcript=normalizeTranscript(note.originalTranscript);note.status='review';await saveNote(note);showNoteReview(note);status('Ожидает проверки');return false}if(sectionOf(note)==='notes'||sectionOf(note)==='treatment'){note.status='done';await saveNote(note);updateChatNote(note);appendChat({role:'assistant',content:sectionOf(note)==='notes'?'Сохранено в заметки.':'Сохранено в лечение.',noteId:note.id});toast(sectionOf(note)==='notes'?'Заметка сохранена.':'Обработка сохранена.');await refresh();return true}await enrichNote(note);await saveNote(note);updateChatNote(note);const objectName=note.entityType==='nucleus'?'отводок':'семью',destination=`Сохранено в ${objectName}${note.family?` №${note.family}`:''}.`,warning=note.analysis?.family_number_conflict?` В распознанной фразе определён номер ${note.family}, модель предлагала ${note.analysis.model_family_number}; сохранён номер из фразы.`:'';appendChat({role:'assistant',content:destination+warning,noteId:note.id});toast('Заметка добавлена в журнал.');refresh();return true}catch(e){if(note.transcript){note.status='pending';await saveNote(note);updateChatNote(note)}toast(e.message);status('Ожидает обработки',true);return false}}
async function processQueue(){if(!navigator.onLine)return;const notes=await allNotes();const review=notes.find(n=>n.status==='review'&&sectionOf(n)===activeType);if(review){showNoteReview(review);return}for(const n of notes.filter(x=>x.status==='pending'&&sectionOf(x)===activeType)){if(!await processNote(n.id))break}}
async function askJournal(question){if(!question.trim())return'';const notes=(await allNotes()).filter(n=>n.transcript&&n.status!=='review'&&sectionOf(n)===activeType).slice(0,180),closed=closedTasks();if(!keyOrder().length)return'Добавьте API-ключи Groq в настройках.';const context=notes.map(n=>{const analysis={...(n.analysis||{}),tasks:(n.analysis?.tasks||[]).map((text,index)=>({text,status:closed.has(`${n.id}:${index}`)?'выполнено':'открыто'}))},entity=activeType==='family'||activeType==='nucleus'?`; тип: ${activeType==='nucleus'?'отводок':'семья'}; номер: ${n.family??'не определён'}; данные: ${JSON.stringify(analysis)}`:'';return`Дата: ${new Date(n.createdAt).toLocaleString('ru-RU')}${entity}; запись: ${n.transcript}`}).join('\n');try{return await complete(`Вопрос: ${question}\n\nРаздел: ${sectionLabel(activeType)}. Учитывай только записи ниже из этого раздела.\nЗаписи раздела:\n${context||'Записей пока нет.'}\n\nИщи по смыслу, синонимам и близким формулировкам. Для запросов о задачах показывай только задания со статусом «открыто», не упоминай закрытые. Отвечай коротко, но если спрашивают перечень — включи все совпадения, каждое отдельной строкой. Не используй информацию из других разделов. В заметках и лечении отвечай только по их записям; в лечении перечисляй дату, средство и объект только если они есть в тексте. Не давай советов по лечению и дозировкам. В семьях и отводках не смешивай типы даже при одинаковом номере. Используй даты и факты только из переданных записей. ${notes.length===180?'В контекст включено не более 180 последних записей.':''}`)}catch(e){return e.message}}
async function refresh(){const notes=await allNotes();renderEntities(notes);const pending=notes.filter(n=>n.status==='pending').length,reviews=notes.filter(n=>n.status==='review').length;status(!navigator.onLine?'Нет сети':reviews?'Расшифровка ждёт проверки':pending?`${pending} в очереди`:'На связи',!navigator.onLine)}
async function setActiveType(type){activeType=type;document.querySelectorAll('[data-type]').forEach(button=>{const active=button.dataset.type===type;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});const standalone=type==='notes'||type==='treatment';document.querySelector('.task-filters').hidden=standalone;$('record-label').textContent=type==='notes'?'Добавить заметку':type==='treatment'?'Записать обработку':'Записать в журнал';$('question-label').textContent=type==='notes'?'Спросить заметки':type==='treatment'?'Спросить лечение':'Спросить журнал';await refresh();if(navigator.onLine)processQueue()}
function bind(){
  $('record-note').onclick=()=>openInput('note');$('record-question').onclick=()=>openInput('question');
  $('choose-text').onclick=editMode;$('choose-voice').onclick=chooseVoice;
  $('input-send').onclick=()=>{if(recorders[inputKind]?.state==='recording'){$('input-send').disabled=true;$('input-send').textContent='Распознаю…';recorders[inputKind].stop()}else submitInput()};
  $('input-back').onclick=()=>{if(reviewNoteId){$('input-dialog').close();return}openInput(inputKind)};
  $('input-close').onclick=()=>{if(recorders[inputKind]?.state==='recording'){toast('Завершите запись перед закрытием.');return}$('input-dialog').close()};
  document.querySelectorAll('[data-type]').forEach(button=>button.onclick=()=>setActiveType(button.dataset.type));
  document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{activeFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===button));refresh()});
  const dialog=$('settings-dialog');$('open-settings').onclick=()=>{const s=settings();$('api-key-1').value=s.key1;$('api-key-2').value=s.key2;dialog.showModal()};document.querySelector('#settings-dialog .settings-close').onclick=()=>dialog.close();
  $('save-settings').onclick=()=>{localStorage.setItem('api-key-1',$('api-key-1').value.trim());localStorage.setItem('api-key-2',$('api-key-2').value.trim());$('settings-status').textContent='Сохранено';setTimeout(()=>{if(dialog.open)dialog.close();$('settings-status').textContent=''},700)};
  document.querySelector('[data-close-actions]').onclick=()=>$('entity-actions-dialog').close();document.querySelector('[data-close-edit]').onclick=()=>$('entity-edit-dialog').close();
  $('edit-entity').onclick=async()=>{if(!activeEntity)return;const notes=notesForEntity(await allNotes(),activeEntity);$('entity-actions-dialog').close();$('edit-entity-type').value=activeEntity.type;$('edit-entity-number').value=activeEntity.family??'';$('edit-queen-year').value=lastNoteValue(notes,'queen_year');$('edit-strength').value=lastNoteValue(notes,'strength');$('edit-feed').value=lastNoteValue(notes,'feed');$('edit-frame-count').value=lastNoteValue(notes,'frame_count');$('entity-edit-title').textContent=`Основная информация · ${entityTitle(activeEntity.type,activeEntity.family)}`;$('entity-edit-dialog').showModal()};
  $('delete-entity').onclick=deleteEntity;$('entity-edit-form').onsubmit=saveEntityEdit;$('history-edit-form').onsubmit=saveHistoryEdit;$('delete-history').onclick=deleteHistoryNote;document.querySelector('[data-close-history]').onclick=()=>$('history-edit-dialog').close();
  window.addEventListener('online',()=>{status('На связи');processQueue()});window.addEventListener('offline',()=>status('Нет сети',true));
}
async function init(){try{db=await openDb();if(navigator.storage?.persist)navigator.storage.persist();bind();await refresh();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});if(navigator.onLine)processQueue()}catch(e){toast('Не удалось открыть журнал: '+e.message)}}
init();
